            if len(research_tasks) >= MAX_RESEARCH_TASKS:
                return handle_api_error("Túl sok aktív feladat", 429)
            research_tasks[task_id] = task
        thread = threading.Thread(target=run_research_task, args=(task_id,), daemon=True)
        thread.start()
        return jsonify({"task_id": task_id}), 201
    except ValueError as e:
        return handle_api_error("Invalid input", 400)
    except Exception as e:
        return handle_api_error("Hiba a kutatás létrehozásakor", 500, e)

@app.route('/api/research/<task_id>', methods=['GET'])
def get_research_status(task_id: str):
    try:
        task_id = sanitize_input(task_id)
        with state_lock:
            task = research_tasks.get(task_id)
        if not task:
            return handle_api_error("Feladat nem található", 404)
        return jsonify(task), 200
    except ValueError as e:
        return handle_api_error("Invalid task_id", 400)
    except Exception as e:
        return handle_api_error("Hiba a feladat lekérésekor", 500, e)

def run_research_task(task_id: str):
    try:
        with state_lock:
            task = research_tasks.get(task_id)
        if not task:
            return
        update_task_status(task_id, "running", 10, 0, "Keresési lekérdezések generálása...")
        queries = generate_search_queries(task["goal"])
