            update_task_status(task_id, "error", 100, 0, "Nem sikerült keresési lekérdezéseket generálni")
            return
        update_task_status(task_id, "running", 25, 0, "Web keresés folyamatban...")
        sources = search_web(queries, task["search_params"])
        if not sources:
            update_task_status(task_id, "error", 100, 0, "Nem találhatók releváns források")
            return
        with state_lock:
            research_tasks[task_id]["sources"] = sources
        update_task_status(task_id, "running", 40, 1, "Tartalom elemzése...")
        analyzed_content = analyze_sources(sources, task["goal"])
        if not analyzed_content:
            update_task_status(task_id, "error", 100, 1, "Nem sikerült elemezni a forrásokat")
            return
        update_task_status(task_id, "running", 70, 2, "Kutatási jelentés írása...")
        report = generate_report(task["goal"], analyzed_content, sources)
        if not report:
            update_task_status(task_id, "error", 100, 2, "Nem sikerült generálni a jelentést")
