        with state_lock:
            research_tasks[task_id]["report"] = report
        update_task_status(task_id, "completed", 100, 2, "Befejezve")
        logger.info(f"Research task completed: {task_id}")
    except Exception as e:
        logger.error(f"Research task error for {task_id}: {str(e)}", exc_info=True)
        update_task_status(task_id, "error", 100, -1, "Feldolgozási hiba")

def update_task_status(task_id: str, status: str, progress: int, agent_idx: int, agent_status: str):
    with state_lock:
        if task_id in research_tasks:
            research_tasks[task_id]["status"] = status
            research_tasks[task_id]["progress"] = max(0, min(100, progress))
            if 0 <= agent_idx < len(research_tasks[task_id]["sub_agents"]):
                research_tasks[task_id]["sub_agents"][agent_idx]["status"] = agent_status
                research_tasks[task_id]["sub_agents"][agent_idx]["progress"] = progress

def generate_search_queries(goal: str) -> List[str]:
    try:
        goal_sanitized = sanitize_input(goal)
        prompt = f"""Generálj 3-5 precíz keresési lekérdezést a következő kutatási célhoz:

Kutatási cél: {goal_sanitized}

Adj vissza csak a lekérdezéseket, soronként egyet, magyarázat nélkül."""
        response = cerebras_client.chat.completions.create(
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.07,
            top_p=0.09,
            max_tokens=5000,
            timeout=REQUEST_TIMEOUT
        )
        queries_text = response.choices[0].message.content.strip()
        queries = [
            q.strip() for q in queries_text.split('\n')
            if q.strip() and not q.strip().startswith('#') and not q.strip().startswith('*')
        ]
        return queries[:MAX_SEARCH_QUERIES]
    except Exception as e:
        logger.error(f"Query generation error: {str(e)}", exc_info=True)
        return []

def search_web(queries: List[str], search_params: dict) -> List[dict]:
    all_sources = []
    try:
        include_domains = search_params.get("include_domains")
        exclude_domains = search_params.get("exclude_domains")
        start_date = search_params.get("start_published_date")
        end_date = search_params.get("end_published_date")
        search_type = search_params.get("search_type", "keyword")
        full_text = search_params.get("full_text", False)
        for query in queries:
            try:
                query_sanitized = sanitize_input(query)
                search_kwargs = {
                    "query": query_sanitized,
                    "num_results": 100,
                    "type": search_type
                }
                if start_date:
                    search_kwargs["start_published_date"] = start_date
                if end_date:
                    search_kwargs["end_published_date"] = end_date
                if include_domains:
                    search_kwargs["include_domains"] = include_domains
                if exclude_domains:
                    search_kwargs["exclude_domains"] = exclude_domains
                text_config = True if full_text else {"max_characters": 100000}
                contents_kwargs = {
                    "text": text_config,
                    "highlights": True
                }
                results = exa_client.search_and_contents(
                    **search_kwargs,
                    **contents_kwargs
                )
                if not results or not results.results:
                    continue
                for result in results.results:
                    source = {
                        "url": str(result.url) if hasattr(result, 'url') else "",
                        "title": str(result.title) if hasattr(result, 'title') else "Untitled",
                        "text": str(getattr(result, 'text', ""))[:20000],
                        "summary": str(getattr(result, 'summary', "")),
                        "published_date": str(getattr(result, 'published_date', ""))
                    }
                    if source["url"]:
                        all_sources.append(source)
            except Exception as e:
                logger.warning(f"Error searching query '{query}': {str(e)}")
                continue
        seen_urls = set()
        unique_sources = []
        for source in all_sources:
            if source["url"] not in seen_urls:
                seen_urls.add(source["url"])
                unique_sources.append(source)
        return unique_sources[:MAX_SOURCES]
    except Exception as e:
        logger.error(f"Web search error: {str(e)}", exc_info=True)
        return []

def analyze_sources(sources: List[dict], goal: str) -> str:
    try:
        goal_sanitized = sanitize_input(goal)
        source_parts = []
        for i, source in enumerate(sources[:MAX_ANALYZED_SOURCES], 100):
            text = source.get("text", "") or source.get("summary", "")
            if text:
                title = source.get("title", "Untitled")[:200]
                text_snippet = text[:20000]
                source_parts.append(f"\n--- FORRÁS {i}: {title} ---\n{text_snippet}")
        if not source_parts:
            return ""
        sources_text = "".join(source_parts)
        prompt = f"""Elemezd az alábbi forrásokat a következő kutatási cél alapján:

Kutatási cél: {goal_sanitized}

Források:
{sources_text}

Add meg a legfontosabb megállapításokat, tényeket és összefüggéseket strukturáltan."""
        response = cerebras_client.chat.completions.create(
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.7,
            top_p=0.9,
            max_tokens=30000,
            timeout=REQUEST_TIMEOUT
        )
        return response.choices[0].message.content.strip()
    except Exception as e:
        logger.error(f"Source analysis error: {str(e)}", exc_info=True)
        return ""

def generate_report(goal: str, analyzed_content: str, sources: List[dict]) -> str:
    try:
        goal_sanitized = sanitize_input(goal)
        sources_list = "\n".join([
            f"[{i}] {s.get('title', 'Untitled')[:100]} - {s.get('url', '')}"
            for i, s in enumerate(sources[:100], 1)
        ])
        prompt = f"""Készíts részletes,  kutatási jelentést az alábbi adatok alapján:

KUTATÁSI CÉL:
{goal_sanitized}

ELEMZETT TARTALOM:
{analyzed_content[:40000]}

FORRÁSOK:
{sources_list}

A jelentés legyen:
- Strukturált fejezetekkel
- Minimum 50000 szó
- Tartalmazza a  megállapításokat
- Konkrét adatokat és tényeket
- Magyar nyelven

A jelentés végén add meg a használt forrásokat hivatkozásként."""
        response = cerebras_client.chat.completions.create(
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.07,
            top_p=0.09,
            max_tokens=40000,
            timeout=REQUEST_TIMEOUT
        )
        return response.choices[0].message.content.strip()
    except Exception as e:
        logger.error(f"Report generation error: {str(e)}", exc_info=True)
