            torus.rotation.y += 0.001;
            renderer.render(scene, camera);
        }
        animate();

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        const sessionId = 'session_' + Math.random().toString(36).substr(2, 9);
        let currentMode = 'chat';
        let currentResearchTaskId = null;
        let researchPollInterval = null;

        const chatHistory = document.getElementById('chat-history');
        const messageInput = document.getElementById('message-input');
        const messageForm = document.getElementById('message-form');
        const sendButton = document.getElementById('send-button');
        const addButton = document.getElementById('add-button');
        const actionPopupMenu = document.getElementById('action-popup-menu');
        const menuResearch = document.getElementById('menu-research');
        const researchView = document.getElementById('research-view');
        const researchBackButton = document.getElementById('research-back-button');
        const researchOptionsOverlay = document.getElementById('research-options-modal-overlay');
        const submitResearchTask = document.getElementById('submit-research-task');
        const toggleAdvancedOptions = document.getElementById('toggle-advanced-options');
        const advancedOptionsContainer = document.getElementById('advanced-options-container');

        addButton.addEventListener('click', () => {
            actionPopupMenu.classList.toggle('visible');
        });

        menuResearch.addEventListener('click', () => {
            actionPopupMenu.classList.remove('visible');
            currentMode = 'research';
            sendButton.classList.remove('mode-chat');
            sendButton.classList.add('mode-research');
            messageInput.classList.add('mode-research');
            messageInput.placeholder = 'Írd le a kutatási célt...';
        });

        toggleAdvancedOptions.addEventListener('click', () => {
            if (advancedOptionsContainer.style.display === 'none' || advancedOptionsContainer.style.display === '') {
                advancedOptionsContainer.style.display = 'block';
                toggleAdvancedOptions.textContent = 'Haladó beállítások elrejtése';
            } else {
                advancedOptionsContainer.style.display = 'none';
                toggleAdvancedOptions.textContent = 'Haladó beállítások megjelenítése';
            }
        });

        messageForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const message = messageInput.value.trim();
            if (!message) return;

            if (currentMode === 'chat') {
                addUserMessage(message);
                messageInput.value = '';
                sendButton.disabled = true;
                const typingIndicator = addTypingIndicator();
                try {
                    await saveMessage({role: 'user', content: message});
                    const history = await getChatHistory();
                    const response = await fetch('/api/chat', {
                        method: 'POST',
                        headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify({messages: history})
                    });
                    const data = await response.json();
                    removeTypingIndicator(typingIndicator);
                    if (data.error) {
                        addAiMessage('Hiba: ' + data.error, true);
                    } else {
                        const aiContent = data.choices[0].message.content;
                        addAiMessage(aiContent);
                        await saveMessage({role: 'assistant', content: aiContent});
                    }
                } catch (error) {
                    removeTypingIndicator(typingIndicator);
                    addAiMessage('Hiba a kérés küldésekor: ' + error.message, true);
                }
                sendButton.disabled = false;
            } else if (currentMode === 'research') {
                document.getElementById('research-goal-summary').textContent = message;
                researchOptionsOverlay.classList.add('visible');
                currentResearchGoal = message;
            }
        });

        let currentResearchGoal = '';

        submitResearchTask.addEventListener('click', async () => {
            const goal = currentResearchGoal;
            const searchType = document.getElementById('search-type').value;
            const startDate = document.getElementById('start-date').value;
            const endDate = document.getElementById('end-date').value;
            const includeDomains = document.getElementById('include-domains').value;
            const excludeDomains = document.getElementById('exclude-domains').value;

            researchOptionsOverlay.classList.remove('visible');
            messageInput.value = '';
            sendButton.classList.remove('mode-research');
            sendButton.classList.add('mode-chat');
            messageInput.classList.remove('mode-research');
            messageInput.placeholder = 'Írj egy üzenetet...';
            currentMode = 'chat';

            const payload = {
                goal,
                search_type: searchType
            };
            if (startDate) payload.start_published_date = new Date(startDate).toISOString();
            if (endDate) payload.end_published_date = new Date(endDate).toISOString();
            if (includeDomains) payload.include_domains = includeDomains;
            if (excludeDomains) payload.exclude_domains = excludeDomains;

            try {
                const response = await fetch('/api/research/create', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify(payload)
                });
                const data = await response.json();
                if (data.error) {
                    addAiMessage('Hiba a kutatás létrehozásakor: ' + data.error, true);
                    return;
                }
                currentResearchTaskId = data.task_id;
                addResearchWidget(data.task_id, goal);
                startResearchPolling(data.task_id);
            } catch (error) {
                addAiMessage('Hiba a kérés küldésekor: ' + error.message, true);
            }
        });

        researchOptionsOverlay.addEventListener('click', (e) => {
            if (e.target === researchOptionsOverlay) {
                researchOptionsOverlay.classList.remove('visible');
                currentMode = 'chat';
                sendButton.classList.remove('mode-research');
                sendButton.classList.add('mode-chat');
                messageInput.classList.remove('mode-research');
                messageInput.placeholder = 'Írj egy üzenetet...';
            }
        });

        researchBackButton.addEventListener('click', () => {
            researchView.classList.remove('visible');
            document.getElementById('chat-view').classList.remove('research-active');
        });

        function addUserMessage(content) {
            const msgDiv = document.createElement('div');
            msgDiv.className = 'message user';
            msgDiv.textContent = content;
            chatHistory.appendChild(msgDiv);
            chatHistory.scrollTop = chatHistory.scrollHeight;
        }

        function addAiMessage(content, isError = false) {
            const msgDiv = document.createElement('div');
            msgDiv.className = 'message ai';
            if (isError) msgDiv.classList.add('error');
            msgDiv.textContent = content;
            chatHistory.appendChild(msgDiv);
            chatHistory.scrollTop = chatHistory.scrollHeight;
        }

        function addTypingIndicator() {
            const msgDiv = document.createElement('div');
            msgDiv.className = 'message ai typing-indicator';
            msgDiv.innerHTML = '<span class="typing-dot"></span><span class="typing-dot"></span><span class="typing-dot"></span>';
            chatHistory.appendChild(msgDiv);
            chatHistory.scrollTop = chatHistory.scrollHeight;
            return msgDiv;
        }

        function removeTypingIndicator(element) {
            element.remove();
        }

        function addResearchWidget(taskId, goal) {
            const widgetDiv = document.createElement('div');
            widgetDiv.className = 'message widget';
            widgetDiv.id = 'widget-' + taskId;
            widgetDiv.innerHTML = `
                <div class="widget-header">
                    <svg xmlns="" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/>
                    </svg>
                    <h3>Kutatási Feladat</h3>
                </div>
                <div class="widget-body">
                    <div class="task-goal">${goal}</div>
                    <div class="widget-status">Állapot: Indítás...</div>
                    <div class="widget-progress-bar">
                        <div class="widget-progress-inner" style="width: 0%;"></div>
                    </div>
                </div>
            `;
            widgetDiv.addEventListener('click', () => {
                openResearchView(taskId);
            });
            chatHistory.appendChild(widgetDiv);
            chatHistory.scrollTop = chatHistory.scrollHeight;
        }

        function updateResearchWidget(taskId, status, progress) {
            const widget = document.getElementById('widget-' + taskId);
            if (!widget) return;
            widget.querySelector('.widget-status').textContent = `Állapot: ${status}`;
            widget.querySelector('.widget-progress-inner').style.width = progress + '%';
        }

        async function startResearchPolling(taskId) {
            if (researchPollInterval) clearInterval(researchPollInterval);
            researchPollInterval = setInterval(async () => {
                try {
                    const response = await fetch(`/api/research/${taskId}`);
                    const data = await response.json();
                    if (data.error) {
                        clearInterval(researchPollInterval);
                        updateResearchWidget(taskId, 'Hiba', 100);
                        return;
                    }
                    updateResearchWidget(taskId, data.status, data.progress);
                    if (data.status === 'completed' || data.status === 'error') {
                        clearInterval(researchPollInterval);
                    }
                } catch (error) {
                    console.error('Polling error:', error);
                }
            }, 2000);
        }

        async function openResearchView(taskId) {
            try {
                const response = await fetch(`/api/research/${taskId}`);
                const data = await response.json();
                if (data.error) {
                    addAiMessage('Hiba a kutatás lekérésekor: ' + data.error, true);
                    return;
                }
                document.getElementById('research-title').textContent = data.goal;
                const agentGrid = document.getElementById('agent-grid');
                agentGrid.innerHTML = '';
                data.sub_agents.forEach(agent => {
                    const agentCard = document.createElement('div');
                    agentCard.className = 'agent-card';
                    const radius = 25;
                    const stroke = 5;
                    const normalizedRadius = radius - stroke * 2;
                    const circumference = normalizedRadius * 2 * Math.PI;
                    const strokeDashoffset = circumference - (agent.progress / 100) * circumference;
                    agentCard.innerHTML = `
                        <svg class="agent-progress-donut" width="60" height="60">
                            <circle class="donut-bg" stroke="rgba(255,255,255,0.1)" fill="transparent" stroke-width="${stroke}" r="${normalizedRadius}" cx="${radius}" cy="${radius}"/>
                            <circle class="donut-fg" stroke="#007AFF" fill="transparent" stroke-width="${stroke}" stroke-dasharray="${circumference} ${circumference}" stroke-dashoffset="${strokeDashoffset}" stroke-linecap="round" r="${normalizedRadius}" cx="${radius}" cy="${radius}"/>
                            <text class="donut-text" x="50%" y="50%" text-anchor="middle" dy="0.3em">${agent.progress}%</text>
                        </svg>
                        <div class="agent-card-info">
                            <div class="agent-card-title">${agent.name}</div>
                            <div class="agent-card-status">${agent.status}</div>
                        </div>
                    `;
                    agentGrid.appendChild(agentCard);
                });
                const sourcesList = document.getElementById('sources-list');
                sourcesList.innerHTML = '';
                data.sources.slice(0, 20).forEach(source => {
                    const sourceItem = document.createElement('div');
                    sourceItem.className = 'similar-link-item';
                    sourceItem.innerHTML = `
                        <div class="icon-placeholder">
                            <svg xmlns="" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1"/>
                            </svg>
                        </div>
                        <div class="item-text" style="flex:1;">
                            <div class="item-title">${source.title}</div>
                            <div class="item-url">${source.url}</div>
                        </div>
                    `;
                    sourcesList.appendChild(sourceItem);
                });
                const reportDisplay = document.getElementById('report-display');
                reportDisplay.textContent = data.report || 'A jelentés még nem érhető el...';
                researchView.classList.add('visible');
                document.getElementById('chat-view').classList.add('research-active');
            } catch (error) {
                addAiMessage('Hiba a kutatás megnyitásakor: ' + error.message, true);
            }
        }

        async function saveMessage(message) {
            await fetch(`/api/chat/history/${sessionId}`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({message})
            });
        }

        async function getChatHistory() {
            const response = await fetch(`/api/chat/history/${sessionId}`);
            const data = await response.json();
            return data.messages || [];
        }

        async function loadChatHistory() {
            try {
                const messages = await getChatHistory();
                messages.forEach(msg => {
                    if (msg.role === 'user') {
                        addUserMessage(msg.content);
                    } else if (msg.role === 'assistant') {
                        addAiMessage(msg.content);
                    }
                });
            } catch (error) {
                console.error('Error loading chat history:', error);
            }
        }

        loadChatHistory();
    </script>
</body>
